--- index.html
+++ index.html
@@ -60,9 +60,9 @@
 function renderUnits(){const empty='<div class="empty-slot">＋</div>';byId('playerField').innerHTML=[...state.playerUnits.map((u,i)=>unitMarkup(u,i,false)),...Array(Math.max(0,3-state.playerUnits.length)).fill(empty)].join('');byId('enemyField').innerHTML=[...state.enemyUnits.map((u,i)=>unitMarkup(u,i,true)),...Array(Math.max(0,3-state.enemyUnits.length)).fill(empty)].join('');document.querySelectorAll('.unit-card').forEach(el=>el.onclick=()=>unitClick(el.dataset.side,Number(el.dataset.index)))}
 function unitMarkup(u,i,enemy){return `<div class="unit-card ${enemy?'enemy-unit':''} ${!enemy&&state.selectedUnit===i?'selected':''}" data-side="${enemy?'enemy':'player'}" data-index="${i}"><div class="unit-title">${u.name}${u.frozen?' ❄':''}</div><div class="unit-art">${u.icon}</div><div class="unit-stats"><span>⚔ ${u.atk}</span><span>♥ ${u.hp}/${u.maxHp}</span></div></div>`}
 function playCard(i){if(state.phase!=='player')return;const c=state.hand[i];if(c.cost>state.mana){toast('Not enough ashen mana.');return}if(c.kind==='Creature'&&state.playerUnits.length>=3){toast('Your formation is full.');return}state.mana-=c.cost;state.hand.splice(i,1);if(c.kind==='Creature'){const u={...clone(c),maxHp:c.hp,owner:'player',sleep:true};state.playerUnits.push(u);addLog(`${c.name} answers your call.`);if(c.effect==='heal1')state.playerLife=Math.min(24,state.playerLife+1);if(c.effect==='freeze'&&state.enemyUnits.length){const target=state.enemyUnits[Math.floor(Math.random()*state.enemyUnits.length)];target.frozen=true;addLog(`${target.name} is frozen in the deep.`)} }else if(c.kind==='Spell'){castSpell(c,'player')}else{state.traps.push({...clone(c),owner:'player'});addLog('A trap is set face down.')};render();checkWin()}
 function castSpell(c,owner){if(c.effect==='heal1'||c.id==='ashen-bloom'){if(owner==='player')state.playerLife=Math.min(24,state.playerLife+4);else state.enemyLife=Math.min(24,state.enemyLife+4);addLog(`${c.name} restores life.`)}else if(c.effect==='sweep'){let targets=owner==='player'?state.enemyUnits:state.playerUnits;targets.forEach(u=>u.hp-=2);if(owner==='player')state.enemyUnits=targets.filter(u=>u.hp>0);else state.playerUnits=targets.filter(u=>u.hp>0);addLog(`${c.name} scorches the opposing formation.`)}else if(c.effect==='surge'){if(owner==='player'){state.enemyLife-=2;state.playerLife=Math.min(24,state.playerLife+2)}else{state.playerLife-=2;state.enemyLife=Math.min(24,state.enemyLife+2)}addLog(`${c.name} drains vitality.`)}else{const targets=owner==='player'?state.enemyUnits:state.playerUnits;if(targets.length){const t=targets[0];t.hp-=c.id==='soul-lance'?3:3;if(t.hp<=0){targets.shift();addLog(`${t.name} falls.`)}else addLog(`${c.name} hits ${t.name} for 3.`)}else{if(owner==='player')state.enemyLife-=3;else state.playerLife-=3;addLog(`${c.name} strikes the opposing duelist for 3.`)}}}
-function unitClick(side,i){if(side==='player'){if(state.phase!=='player')return;const u=state.playerUnits[i];if(u.sleep){toast('A creature must wait one turn before attacking.');return}state.selectedUnit=state.selectedUnit===i?null:i;render();return}if(state.selectedUnit===null){toast('Choose one of your ready creatures first.');return}attack(state.selectedUnit,i)}
+function unitClick(side,i){if(side==='player'){if(state.phase!=='player')return;const u=state.playerUnits[i];if(u.sleep){toast('A creature must wait one turn before attacking.');return}if(state.selectedUnit===i&&!state.enemyUnits.length){directAttack(i);return}state.selectedUnit=state.selectedUnit===i?null:i;render();return}if(state.selectedUnit===null){toast('Choose one of your ready creatures first.');return}attack(state.selectedUnit,i)}
 function attack(ai,ei){const a=state.playerUnits[ai],d=state.enemyUnits[ei];if(!a||!d)return;if(d.frozen){d.frozen=false;addLog(`${d.name} thaws as the attack begins.`)}else{a.hp-=d.atk;d.hp-=a.atk;addLog(`${a.name} and ${d.name} clash: ${a.atk} for ${d.hp+a.atk}, ${d.atk} back.`);if(a.effect==='drain')state.enemyLife=Math.max(0,state.enemyLife-1);if(a.hp<=0){addLog(`${a.name} is destroyed.`);state.playerUnits.splice(ai,1)}if(d.hp<=0){addLog(`${d.name} is destroyed.`);state.enemyUnits.splice(ei,1)}}state.selectedUnit=null;render();checkWin()}
 function directAttack(i){const a=state.playerUnits[i];if(a.sleep||state.phase!=='player')return;if(state.enemyUnits.length){toast('Defeat enemy creatures before attacking directly.');return}if(state.traps.length){const trap=state.traps.shift();if(trap.id==='snare-of-bones'){state.playerUnits.splice(i,1);addLog('Bone Snare triggers — your attacker is destroyed!');state.selectedUnit=null;render();return}if(trap.id==='warding-rune'){state.playerLife=Math.max(0,state.playerLife- Math.max(0,a.atk-4));addLog(`Warding Rune absorbs the strike.`);state.selectedUnit=null;render();checkWin();return}}state.enemyLife-=a.atk;addLog(`${a.name} strikes the enemy duelist for ${a.atk}.`);if(a.effect==='drain')state.enemyLife=Math.max(0,state.enemyLife-1);state.selectedUnit=null;render();checkWin()}
 function onPlayerFieldClick(){/* delegated through selected-card second click */}
 function doEnemyTurn(){if(state.phase!=='player')return;state.phase='enemy';state.selectedUnit=null;state.playerUnits.forEach(u=>u.sleep=false);render();setTimeout(()=>{if(state.playerLife<=0)return;state.maxMana=Math.min(6,state.maxMana+1);state.mana=state.maxMana;const playable=state.deckPile.filter(c=>c.cost<=state.mana);if(playable.length&&state.enemyUnits.length<3){const c=playable.sort((a,b)=>b.atk-a.atk)[0];const ix=state.deckPile.indexOf(c);state.deckPile.splice(ix,1);if(c.kind==='Creature'){state.enemyUnits.push({...clone(c),maxHp:c.hp,sleep:true});addLog(`The ${deckById(state.deck).enemy} summons ${c.name}.`)}else if(c.kind==='Spell'){castSpell(c,'enemy')}else{state.traps.push({...clone(c),owner:'enemy'});addLog('Your opponent sets a trap.')}}if(state.enemyUnits.length){const attacker=state.enemyUnits.find(u=>!u.sleep&&!u.frozen);if(attacker){if(state.playerUnits.length){const defender=state.playerUnits[0];if(state.traps.length){const trap=state.traps.shift();if(trap.id==='snare-of-bones'){state.enemyUnits.splice(state.enemyUnits.indexOf(attacker),1);addLog('Bone Snare destroys the attacking creature!')}else{state.playerLife=Math.max(0,state.playerLife-Math.max(0,attacker.atk-4));addLog('Warding Rune absorbs the attack.')}}else{attacker.hp-=defender.atk;defender.hp-=attacker.atk;addLog(`${attacker.name} attacks ${defender.name}.`);if(attacker.hp<=0){state.enemyUnits.splice(state.enemyUnits.indexOf(attacker),1);addLog(`${attacker.name} is destroyed.`)}if(defender.hp<=0){state.playerUnits.shift();addLog(`${defender.name} falls.`)}}}else{if(state.traps.length){const trap=state.traps.shift();if(trap.id==='snare-of-bones'){state.enemyUnits.splice(state.enemyUnits.indexOf(attacker),1);addLog('Bone Snare destroys the attacker!')}else{state.playerLife=Math.max(0,state.playerLife-Math.max(0,attacker.atk-4));addLog('Warding Rune absorbs the attack.')}}else{state.playerLife-=attacker.atk;addLog(`${attacker.name} attacks you for ${attacker.atk}.`)}}}}if(state.playerLife<=0){render();finish(false);return}state.playerUnits.forEach(u=>u.sleep=false);state.enemyUnits.forEach(u=>u.sleep=false);state.turn++;state.phase='player';state.maxMana=Math.min(6,state.maxMana+1);state.mana=state.maxMana;draw();state.playerUnits.forEach(u=>{if(u.effect==='regen')state.playerLife=Math.min(24,state.playerLife+1)});render();checkWin()},650)}

