 const SHOP=[{id:'dark-sigil',name:'Dark Sigil',icon:'🌑',price:55,desc:'A forbidden seal. Add a Soul Lance to your deck.'},{id:'field-medic',name:'Estus Flask',icon:'🍷',price:45,desc:'Restore 6 life before the next duel.'},{id:'mystery-pack',name:'Lost Reliquary',icon:'📦',price:70,desc:'Add two signature cards from your champion.'},{id:'soul-cache',name:'Soul Cache',icon:'✦',price:0,desc:'A modest offering from the merchant. Claim 25 souls once.'}];
